}

/**
 * Merge fromId customer into intoId, reassigning all invoices.
 * @param {Array} customers
 * @param {Array} invoices
 * @param {string} fromId
 * @param {string} intoId
 * @returns {{ ok: true, value: { customers: Array, invoices: Array } } | { ok: false, error: string }}
 */
export function mergeCustomers(customers, invoices, fromId, intoId) {
  const normalizedFrom = normalizeId(fromId);
  const normalizedInto = normalizeId(intoId);

  if (normalizedFrom === normalizedInto) {
    return fail('SAME_CUSTOMER');
  }

  const fromExists = customers.some((c) => c.id === normalizedFrom);
  const intoExists = customers.some((c) => c.id === normalizedInto);

  if (!fromExists || !intoExists) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  const mergedCustomers = customers.filter((c) => c.id !== normalizedFrom);
  const mergedInvoices = invoices.map((inv) => ({
    ...inv,
    customerId: inv.customerId === normalizedFrom ? normalizedInto : inv.customerId,
  }));

  return ok({ customers: mergedCustomers, invoices: mergedInvoices });
}

